
cc.Class({
    extends: require('LMSlots_Logic_Base'),

    properties: {
        
    },


    InitCommComponent:function() {
        this._super();

        //ui管理
        let uinode = cc.find('safe_node/gameUI',this.node);
        let scp_ui = uinode.addComponent('Fenrir_UIMgr');
        cc.vv.gameData.setUIMgrScript(scp_ui);
        scp_ui.Init();

        let bonusuinode = cc.find('safe_node/bonusgame',this.node);
        let scp_bonus = bonusuinode.addComponent('Fenrir_BonusGameMgr');
        cc.vv.gameData.setBonusGameMgr(scp_bonus);
        scp_bonus.Init();

        let node_superFree = cc.find('safe_node/super_free',this.node);
        let scp_superFree = node_superFree.addComponent('Fenrir_SFreeMgr');
        cc.vv.gameData.setSuperFreeMgr(scp_superFree);
        scp_superFree.Init();

        let node_box = cc.find("safe_node/boxGame", this.node);
        let scp_box = node_box.addComponent('Fenrir_BoxUI');
        cc.vv.gameData.setBoxGameMgr(scp_box);
        scp_box.Init();
    },
});
