
cc.Class({
    extends: cc.Component,

    properties: {
        // boxUIScript:cc.Component,
        _bonusAddSpinList:[],
        _bonusPickItemList:[],
        _canAddSpins:false,

    },

    Init(){
        this._bonusGameStartUI = cc.find('bonusGameStartUI',this.node);
        this._bonusGameEndUI = cc.find('bonusGameEndUI',this.node);
        this._bonusDoubleStartUI = cc.find("bonusDoubleStartUI", this.node);
        this._freeGameStartUI = cc.find('freeGameStartUI',this.node);
        this._freeGameEndUI = cc.find('freeGameEndUI',this.node);
        this._bonusGameAddSpinsUI = cc.find('bonusGameAddSpins',this.node);
        this._bonusGamePickOneUI = cc.find("bonusGamePickOneUI", this.node);
        this._superFreeStartUI = cc.find("superFreeStartUI", this.node);
        this._bonusDoubleWinUI = cc.find("bonusDoubleWinUI", this.node);
        this._bonusGameStartUI.active = false;
        this._bonusGameEndUI.active = false;
        this._bonusDoubleStartUI.active = false;
        this._freeGameStartUI.active = false;
        this._freeGameEndUI.active = false;
        this._bonusGamePickOneUI.active = false;
        this._superFreeStartUI.active = false;
        this._bonusDoubleWinUI.active = false;
        for(let i = 1; i <= 3; i++) {
            let item = cc.find("mainnode/number" + i, this._bonusGameAddSpinsUI);
            this._bonusAddSpinList.push(item);
        }
        for(let i = 1; i <= 5; i++) {
            let item = cc.find("mainnode/item" + i, this._bonusGamePickOneUI);
            this._bonusPickItemList.push(item);
        }

        this._transition1 = cc.find('transition1',this.node);
        this._transition2 = cc.find('transition2',this.node);
        this._transition1.active = false;
        this._transition2.active = false;
        
    },

    //显示bonus游戏开始界面  type-2:不显示开始按钮
    async showBonusStartUI(freetimes, type){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playEffect("bonus_start_show");

            this._bonusGameStartUI.active = true;
            let mainnode = cc.find("mainnode", this._bonusGameStartUI);
            mainnode.setScale(0);
            cc.tween(mainnode).to(0.5,{scale:1},{easing:"backOut"}).start();

            let timesnode = cc.find('mainnode/freetimes', this._bonusGameStartUI);
            timesnode.getComponent(cc.Label).string = freetimes;

            let btn_start = cc.find('mainnode/btn_start',this._bonusGameStartUI);
            if(type && type === 2){
                btn_start.active = false;

                await cc.vv.gameData.awaitTime(1.5);
                cc.tween(mainnode).to(0.5, {scale: 0}, {easing: "backIn"}).start();
                await cc.vv.gameData.awaitTime(0.5);
                this._bonusGameStartUI.active = false;

                success();
            } else {
                btn_start.active = true;
                await cc.vv.gameData.awaitTime(0.5);

                let self = this;
                let clickFunc = function(){
                    Global.SlotsSoundMgr.playEffect("pop_click");
                    btn_start.getComponent(cc.Button).interactable = false;
                    cc.tween(mainnode)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .call(()=>{
                            self._bonusGameStartUI.active = false;
                            success();
                        })
                        .start();
                };
                cc.vv.gameData.checkAutoPlay(btn_start, clickFunc);
                btn_start.off("click");
                btn_start.getComponent(cc.Button).interactable = true;
                btn_start.on("click", async()=>{
                    btn_start.stopAllActions()
                    clickFunc()
                });
            }
        })
    },

    //显示bonus游戏结束界面
    showBonusEndUI(subgamedata){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playEffect("bonus_end_show");

            this._bonusGameEndUI.active = true;
            let mainnode = cc.find("mainnode", this._bonusGameEndUI);
            mainnode.setScale(0);
            cc.tween(mainnode).to(0.5,{scale:1},{easing:"backOut"}).start();

            let coinnode = cc.find('bgcoin/getcoin',mainnode);
            Global.doRoallNumEff(coinnode,0,subgamedata.winCoin,1,null,null,0,true);

            let bottom = cc.find("bottombg", mainnode);
            let pos = bottom.position;
            bottom.position = cc.v2(0,0);
            bottom.active = false;

            await cc.vv.gameData.awaitTime(0.3);
            bottom.active = true;
            cc.tween(bottom).to(0.5,{position:pos}).start();

            await cc.vv.gameData.awaitTime(0.5);
            let btn_collect = cc.find('btn_collect',bottom);

            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect("pop_click");
                btn_collect.getComponent(cc.Button).interactable = false;
                cc.tween(bottom).to(0.5,{position:cc.v2(0,0)}).start();
                cc.tween(mainnode)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(()=>{
                        self._bonusGameEndUI.active = false;
                        bottom.position = pos;
                        success();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(btn_collect, clickFunc);
            btn_collect.off("click");
            btn_collect.getComponent(cc.Button).interactable = true;
            btn_collect.on("click", async()=>{
                btn_collect.stopAllActions();
                clickFunc()
            });
        });
    },

    async showBonusAddSpinsUI(){
        return new Promise(async (success, failed) => {
            this._bonusGameAddSpinsUI.active = true;
            let mainnode = cc.find("mainnode", this._bonusGameAddSpinsUI);
            mainnode.setScale(0);
            cc.tween(mainnode).to(0.5,{scale:1},{easing:"backOut"}).start();

            this._bonusAddSpinList.forEach(item=>{
                cc.vv.gameData.playSpine(cc.find("aninode",item),'animation1',true);
                let atlas = cc.vv.gameData.GetAtlasByName("dialog")
                cc.find('addnum',item).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame('theme158_dialog_text19')

                item.off("click");
                item.getComponent(cc.Button).interactable = false;
                item.on("click", ()=>{
                    this.onClickBonusAddSpins(item, success);
                })
            });

            await cc.vv.gameData.awaitTime(0.5);
            this._canAddSpins = true;
            this._bonusAddSpinList.forEach(item=>{item.getComponent(cc.Button).interactable = true;})
            cc.vv.gameData.checkAutoPlay( this._bonusAddSpinList[0],
                ()=>{this.onClickBonusAddSpins(this._bonusAddSpinList[0], success)});
        });
    },

    async onClickBonusAddSpins(item, success){
        if( !this._canAddSpins ){
            return
        }
        this._canAddSpins = false;
        this._bonusAddSpinList[0].stopAllActions();
        Global.SlotsSoundMgr.playEffect("extra_respin");
        this._bonusAddSpinList.forEach(item=>{item.getComponent(cc.Button).interactable = false;})

        let idx = parseInt(item.name.substr(-1,1));
        let reqdata = {rtype:2,choiceId:idx};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code == 200){
            //展示次数
            let extraspins = result.data.extraSpins;
            let bonusgame = result.data.bonusGame;
            cc.vv.gameData.setBonusGame(bonusgame);

            for(let i=0;i<extraspins.length;i++){
                let choiceid = i+1;
                let numbernode = cc.find(cc.js.formatStr('mainnode/number%s/addnum',choiceid),this._bonusGameAddSpinsUI);
                let atlas = cc.vv.gameData.GetAtlasByName("dialog")
                numbernode.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame('theme158_dialog_num'+extraspins[i])
                if(choiceid == result.data.choiceId){
                    //播放动画
                    let numbernode = cc.find(cc.js.formatStr('mainnode/number%s/aninode',choiceid),this._bonusGameAddSpinsUI);
                    cc.vv.gameData.playSpine(numbernode,'animation2',false,null);
                }
            }

            await cc.vv.gameData.awaitTime(3);
            let mainnode = cc.find("mainnode", this._bonusGameAddSpinsUI);
            cc.tween(mainnode).to(0.5,{scale:0},{easing:"backIn"}).start();
            await cc.vv.gameData.awaitTime(0.5);
            this._bonusGameAddSpinsUI.active = false;

            success();
        }
    },

    // 免费游戏开始界面
    async showFreeGameStartUI(cnt,type){
        return new Promise(async(success, failed) => {
            Global.SlotsSoundMgr.playEffect("free_dialog_start_show");

            this._freeGameStartUI.active = true;

            let mainnode = cc.find("mainnode", this._freeGameStartUI);
            let spcoin = cc.find("mainnode/bg_coin/getcoin", this._freeGameStartUI);
            // let totalfree = cc.vv.gameData.GetTotalFree();
            let atlas = cc.vv.gameData.GetAtlasByName("dialog");
            spcoin.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame('theme158_dialog_num' + cnt);

            mainnode.scale = 0;
            cc.tween(mainnode).to(0.5, {scale: 1}, {easing: "backOut"}).start();

            let btn_start = cc.find('mainnode/btn_start',this._freeGameStartUI);
            btn_start.active = !(type == "again");

            await cc.vv.gameData.awaitTime(0.5);
            if (type == "again"){

                await cc.vv.gameData.awaitTime(1);
                cc.tween(mainnode).to(0.5, {scale: 0}, {easing: "backIn"}).start();
                await cc.vv.gameData.awaitTime(0.5);
                this._freeGameStartUI.active = false;

                success();

            } else {

                let self = this;
                let clickFunc = function(){
                    Global.SlotsSoundMgr.playEffect("pop_click");
                    btn_start.getComponent(cc.Button).interactable = false;
                    cc.tween(mainnode)
                        .to(0.5, {scale: 0}, {easing: "backIn"})
                        .call(()=>{
                            self._freeGameStartUI.active = false;
                            success();
                        })
                        .start();
                }
                cc.vv.gameData.checkAutoPlay(btn_start, clickFunc);
                btn_start.off("click");
                btn_start.getComponent(cc.Button).interactable = true;
                btn_start.on("click", async()=>{
                    btn_start.stopAllActions()
                    clickFunc()
                });
            }
        });
    },

    //显示免费游戏结束界面
    async showFreeGameEndUI() {
        return new Promise(async (success, failed) => {
            if(cc.vv.gameData.isSuperFree()){
                Global.SlotsSoundMgr.playEffect("collect_popclose");
            } else {
                Global.SlotsSoundMgr.playEffect("free_dialog_collect_show");
            }

            this._freeGameEndUI.active = true;

            let mainnode = cc.find("mainnode", this._freeGameEndUI);
            let lblcoin = cc.find('mainnode/bg_coin/getcoin',this._freeGameEndUI);
            let nWin = cc.vv.gameData.getFreeWinCoin();
            Global.doRoallNumEff(lblcoin,0,nWin,1,null,null,0,true);

            mainnode.scale = 0;
            cc.tween(mainnode).to(0.5, {scale: 1}, {easing: "backOut"}).start();

            await cc.vv.gameData.awaitTime(0.5);
            let btn_collect = cc.find('mainnode/btn_collect',this._freeGameEndUI);

            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect("pop_click");
                btn_collect.getComponent(cc.Button).interactable = false;
                cc.tween(mainnode)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(()=>{
                        self._freeGameEndUI.active = false;
                        success();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(btn_collect, clickFunc);
            btn_collect.off("click");
            btn_collect.getComponent(cc.Button).interactable = true;
            btn_collect.on("click", async()=>{
                btn_collect.stopAllActions()
                clickFunc()
            });
        })
    },

    // 商店获得bonus游戏开始游戏
    async showBonusDoubleStartUI(){
        return new Promise(async(success, failed) => {
            this._bonusDoubleStartUI.active = true;

            let mainnode = cc.find("mainnode", this._bonusDoubleStartUI);
            mainnode.setScale(0);
            cc.tween(mainnode).to(0.5,{scale:1},{easing:"backOut"}).start();

            await cc.vv.gameData.awaitTime(0.5);
            let btn_collect = cc.find("bottombg/btn_collect", mainnode);

            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect("pop_click");
                btn_collect.getComponent(cc.Button).interactable = false;
                cc.tween(mainnode)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(()=>{
                        self._bonusDoubleStartUI.active = false;
                        success();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_collect, clickFunc);
            btn_collect.off("click");
            btn_collect.getComponent(cc.Button).interactable = true;
            btn_collect.on("click", async()=>{
                btn_collect.stopAllActions();
                clickFunc();
            });
        })
    },

    // 商店得到bonus游戏选择游戏次数
    async showBonusGamePickOneUI(){
        return new Promise(async(success, failed) => {
            this._bonusGamePickOneUI.active = true;
            let mainnode = cc.find("mainnode", this._bonusGamePickOneUI);
            mainnode.setScale(0);
            cc.tween(mainnode).to(0.5,{scale:1},{easing:"backOut"}).start();
            cc.find("mainnode/kuangsp",this._bonusGamePickOneUI).active = false;

            this._bonusPickItemList.forEach(item=>{
                cc.find("di_def", item).active = true;
                cc.find("wenhao", item).active = true;
                cc.find("result", item).active = false;
                cc.find("dongzhu", item).active = false;
                item.off("click");

                item.getComponent(cc.Button).interactable = false;
                item.on("click", ()=>{
                    this.onClickBonusPickItem(item, success);
                })
            });
            await cc.vv.gameData.awaitTime(0.5);
            this._bonusPickItemList.forEach(item=>{item.getComponent(cc.Button).interactable = true;})
        })
    },

    async onClickBonusPickItem(item, success){
        this._bonusPickItemList.forEach(item=>{item.getComponent(cc.Button).interactable = false});

        let idx = parseInt(item.name.substring("item".length));
        let reqdata = {rtype:1,choiceId:idx};
        let msg = await cc.vv.gameData.reqSubGame(reqdata);
        if (msg.code == 200){
            Global.SlotsSoundMgr.playEffect("respin_pick");
            let bonusGame = msg.data.bonusGame;
            let bonusType = msg.data.bonusTypes;
            let result = msg.data.result;
            cc.vv.gameData.setBonusGame(bonusGame);

            cc.find("di_def", item).active = false;
            cc.find("wenhao", item).active = false;
            cc.find("result", item).active = true;
            cc.find("dongzhu", item).active = false;

            let atlas = cc.vv.gameData.GetAtlasByName("dialog");
            let pic1 = "theme158_dialog_6_text" + result.spinCnt;
            cc.find("result", item).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame(pic1)
            let kuangsp = cc.find("mainnode/kuangsp",this._bonusGamePickOneUI);
            kuangsp.active = true;
            kuangsp.getComponent(sp.Skeleton).setAnimation(0,"animation"+idx,true);
            await cc.vv.gameData.awaitTime(0.5);

            Global.SlotsSoundMgr.playEffect("respin_reveal");
            for(let i = 0; i < this._bonusPickItemList.length; i++){
                if(i+1 != idx){
                    let restItem = this._bonusPickItemList[i];
                    cc.find("di_def", restItem).active = false;
                    cc.find("wenhao", restItem).active = false;
                    cc.find("result", restItem).active = true;
                    cc.find("dongzhu", restItem).active = true;

                    let pic2 = "theme158_dialog_6_text" + bonusType[i].spinCnt;
                    cc.find("result", restItem).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame(pic2)
                    cc.vv.gameData.playSpine(cc.find("dongzhu", restItem),"animation",false);

                }
            }

            await cc.vv.gameData.awaitTime(2);
            cc.tween(cc.find("mainnode", this._bonusGamePickOneUI)).to(0.5,{scale:0},{easing:"backIn"}).start();
            await cc.vv.gameData.awaitTime(0.5);
            this._bonusGamePickOneUI.active = false;

            success();
        }
    },

    // 商店完成一页后的免费游戏开始页面
    async showSuperFreeStartFreeUI(page){
        return new Promise(async(success, failed) => {
            Global.SlotsSoundMgr.playEffect("collect_popup");

            this._superFreeStartUI.active = true;
            let mainnode = cc.find("mainnode", this._superFreeStartUI);
            mainnode.setScale(0);
            cc.tween(mainnode).to(0.5,{scale:1},{easing:"backOut"}).start();

            let atlas = cc.vv.gameData.GetAtlasByName("dialog");
            cc.find("bg_cnt/spr_cnt", mainnode).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame('theme158_dialog_num' + cc.vv.gameData.GetTotalFree());
            cc.find("spr_page", mainnode).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme158_dialog_win"+page);

            await cc.vv.gameData.awaitTime(0.5);
            let btn_start = cc.find('btn_start',mainnode);

            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect("pop_click");
                btn_start.getComponent(cc.Button).interactable = false;
                cc.tween(mainnode)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(()=>{
                        self._superFreeStartUI.active = false;
                        success();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_start, clickFunc);
            btn_start.off("click");
            btn_start.getComponent(cc.Button).interactable = true;
            btn_start.on("click", async()=>{
                btn_start.stopAllActions();
                clickFunc();
            });
        })
    },

    // bonus全满后弹窗 type:1-下面slots 2-上面slots
    showBonusDoubleWin(type){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("double_popup");

            this._bonusDoubleWinUI.active = true;
            cc.find("mainnode1", this._bonusDoubleWinUI).active = type === 1;
            cc.find("mainnode2", this._bonusDoubleWinUI).active = type === 2;

            let showNode =  cc.find((type===1)?"mainnode1":"mainnode2", this._bonusDoubleWinUI);

            cc.find("bg_1", showNode).active = type === 1;
            cc.find("bg_2", showNode).active = type === 2;
            let bg = cc.find("bg_"+type, showNode);
            let spine = cc.find("spine", showNode);

            bg.setScale(0);
            cc.tween(bg).to(0.5, {scale:1}, {easing:"backOut"}).start();
            cc.vv.gameData.playSpine(spine, cc.js.formatStr("animation%s_1", type), false,function () {
                cc.vv.gameData.playSpine(spine, cc.js.formatStr("animation%s_2", type), true)
            });

            await cc.vv.gameData.awaitTime(1.5);
            cc.tween(bg).to(0.5, {scale:0}, {easing:"backIn"}).start();
            cc.vv.gameData.playSpine(spine, cc.js.formatStr("animation%s_3", type), false);

            await cc.vv.gameData.awaitTime(0.5);
            this._bonusDoubleWinUI.active = false;
            success();
        })
    },


    // bonus游戏切屏动画
    playBonusQPAnim(){
        Global.SlotsSoundMgr.playEffect("transition2");

        let self = this;
        cc.vv.gameData.playSpine(this._transition2,'animation',false,function () {
            self._transition2.active = false;
        });
    },

    // 免费游戏切屏动画
    playFreeQPAnim(){
        Global.SlotsSoundMgr.playEffect("transition1");

        let self = this;
        cc.vv.gameData.playSpine(this._transition1,'animation',false,function () {
            self._transition1.active = false;
        });
    },

});
