//FreeGame = 1,  -- 触发免费
//Coin = 2,  -- 直接奖励物品
//BonusGame = 3,  -- 触发bonus游戏

cc.Class({
    extends: cc.Component,

    properties: {
        pos:0
    },

    onLoad () {
        this._baoxiangSpNode = cc.find('baoxiangspine',this.node);
        this._costShowNode = cc.find('bg_show',this.node);
        Global.btnClickEvent(this.node,this.onBoxEvent,this)

        // cc.find("box_tip", this.node.parent).active = false;
    },

    //初始化解锁宝箱状态
    showBoxState(itemdetail, isInit){
        this._costShowNode.active = false;
        cc.find('baoxiang',this.node).active = false;
        let aniname = this.getSpineName(itemdetail.type);
        if(isInit){
            cc.vv.gameData.playSpine(this._baoxiangSpNode,aniname+'_1',true);
        } else {
            let self = this;
            cc.vv.gameData.playSpine(this._baoxiangSpNode,aniname,false, function () {
                cc.vv.gameData.playSpine(self._baoxiangSpNode,aniname+'_1',true);
            });
        }

        let getcoin = cc.find('getcoin',this.node);
        if(itemdetail.type == 2){
            getcoin.active = true;
            getcoin.getComponent(cc.Label).string = Global.convertNumToShort(itemdetail.coin,1000,0);

            if(!isInit){
                getcoin.setScale(0);
                cc.tween(getcoin).to(0.5,{scale:1},{easing:'backOut'}).start();
            }
        } else {
            getcoin.active = false;
        }
    },

    //切换页面更新宝箱
    // resetState(isreset){
    //     if(this._boxState == 4&&!isreset)
    //        return;
    //     this._costShowNode.active = true;
    //     this._baoxiangSpNode.active = false;
    //     cc.find('getcoin',this.node).active = false;
    // },

    //改变宝箱状态(未解锁1/解锁可以购买2/解锁不能购买3)增加已经购买4
    changeBoxState(pageid,state){
        this._pageId = pageid;
        this._boxState = state;
    },

    //点击宝箱
    async onBoxEvent(){
        if(this._boxState == 3){
            this.showTip()
        }

        if(this._boxState != 2)
            return;

        if(!cc.vv.gameData.canClickBox()){
            return;
        }

        cc.vv.gameData.setCanClickBox(false);
        Global.SlotsSoundMgr.playEffect("chest_open");
        let reqdata = {rtype:4,pageId:this._pageId,choiceId:this.pos};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code == 200 && !result.spcode){
            cc.vv.gameData.updatePawStore(result.data.pawStore);
            let selectRes = result.data.result;

            //点击结果刷新
            this.updateBox(selectRes);
            await cc.vv.gameData.awaitTime(0.5);

            if (selectRes.coin && selectRes.coin > 0){
                this.updateCoin(selectRes.coin);
            }

            if(selectRes.bonusGame || selectRes.freeInfo || selectRes.pageReward) {
                cc.vv.gameData.getBoxGameMgr().gainSpecial(selectRes);

            } else {
                cc.vv.gameData.setCanClickBox(true);
            }
        }
    },

    //获取播放动画名
    getSpineName(type){
        switch (type) {
            case 1:return 'animation3';
            case 2:return 'animation1';
            case 3:return 'animation2';
            default:return 'animation1';
        }
    },

    //更新宝箱
    updateBox(result){
        this.changeBoxState(this._pageId,4);
        this.showBoxState(result,false);
        cc.vv.gameData.getBoxGameMgr().updatePawNum();
        cc.vv.gameData.getBoxGameMgr().updataOtherBox();
    },

    //更新赢钱
    updateCoin(coin){
        if(coin && coin > 0){
            cc.vv.gameData.AddCoin(coin);
            cc.vv.gameData.GetBottomScript().SetWin(coin);
            cc.vv.gameData.GetTopScript().ShowCoin();
        }
    },

    showTip(){
        cc.vv.gameData.getBoxGameMgr().showBoxTip(this.node);
        // let box_tip = cc.find("box_tip", this.node.parent);
        // box_tip.stopAllActions();
        // if(box_tip.active){
        //     box_tip.runAction(cc.sequence(
        //         cc.scaleTo(box_tip.scaleX/2,0,0),
        //         cc.callFunc(()=>{ box_tip.active = false;})
        //     ))
        // } else {
        //     box_tip.position = this.node.position;
        //     box_tip.active = true;
        //     box_tip.setScale(0);
        //     box_tip.runAction(cc.sequence(
        //         cc.scaleTo(0.5,1,1),
        //         cc.delayTime(1),
        //         cc.scaleTo(0.5,0,0),
        //         cc.callFunc(()=>{ box_tip.active = false;})
        //     ))
        // }
    },
});
