// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _slotsNodeList:[],
        _slotsScpList:[],
    },

    // LIFE-CYCLE CALLBACKS:

    Init () {
        this._mainNode = cc.find("mainnode", this.node);

        this._slots = cc.find("slots", this._mainNode);
        for (let i = 1; i <= 4; i++){
            let slot = cc.find("slots_"+i, this._slots);
            let scp = slot.addComponent("Fenrir_SFreeSlots");
            scp.Init(i);
            this._slotsNodeList.push(slot);
            this._slotsScpList.push(scp);
        }

        this._mainNode.active = false;
    },

    start () {

    },

    //点击旋转按钮调用
    StartMove(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotCnt) {
                this._slotsScpList[i].StartMove();
            }
        }
    },

    //点击停止按钮调用
    StopMove:function(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotCnt) {
                this._slotsScpList[i].StopMove();
            }
        }
    },

    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine:function(msg){
        let freeGameSlots = msg.freeGameSlots;

        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotCnt) {
                this._slotsScpList[i].onMsgSpine(freeGameSlots[i]);
            }
        }

    },

    async OnSpinEnd(){
        for (let i = 0; i < this._slotsNodeList.length; i++) {
            if (i < this._slotCnt) {
                this._slotsScpList[i].OnSpinEnd();
            }
        }

        let self = this
        // 底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise((sucess, failed)=>{
            cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin,nTotal,true,function () {
                sucess()
            });
        });

        if(cc.vv.gameData.isNormalFreeOver()){

            this.endSuperFree();

            return ;
        }

        cc.vv.gameData.GetSlotsScript().CanDoNextRound()
    },

    GetLastStopReelIdx(){
        return this._slotsScpList[0].GetLastStopReelIdx();
    },


    // 初始化显示slots
    initShowSlotsDate(){
        Global.SlotsSoundMgr.playBgm("free_bgm");

        this.node.active = true;
        this._mainNode.active = true;

        let pageReward = cc.vv.gameData.getPageReward();
        this._slotCnt = pageReward.slotCnt;
        let wildCols = pageReward.wildCols;
        for (let i = 0; i < this._slotsNodeList.length; i++){
            if(i < this._slotCnt){
                this._slotsNodeList[i].active = true;
                // cc.find("frame_top", this._slotsNodeList[i]).active = i+1 === this._slotCnt;
                this._slotsScpList[i].iniAllSymbol();
                this._slotsScpList[i].setWildCols(wildCols);
            } else {
                this._slotsNodeList[i].active = false
            }
        }

        this.initWolfState();
        this.initStoreState();
        this.setSlotsScale();
    },

    async endSuperFree(){
        await cc.vv.gameData.awaitTime(1);
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        await cc.vv.gameData.getUIMgr().showFreeGameEndUI();
        cc.vv.gameData.getUIMgr().playFreeQPAnim();
        await cc.vv.gameData.awaitTime(0.6);
        cc.vv.gameData.GetBottomScript().ShowFreeModel(false);
        Global.SlotsSoundMgr.stopBgm();

        this._mainNode.active = false;
        for (let i = 0; i < this._slotsNodeList.length; i++){
            this._slotsScpList[i].iniAllSymbol();
        }

        await cc.vv.gameData.awaitTime(2);
        cc.vv.gameData.setIsSuperFree(false);

        await new Promise((success)=>{
            let nWin = cc.vv.gameData.GetGameWin()
            let nTotal = cc.vv.gameData.GetGameTotalFreeWin()
            cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin,nTotal,true,()=>{
                success();
            });
        });

        cc.vv.gameData.GetBottomScript().CanDoNextRound();

        if(cc.vv.gameData.isBoxGame()){
            cc.vv.gameData.getBoxGameMgr().openBoxUI();
            cc.vv.gameData.setIsBoxGame(false)
        }
    },

    // 初始化展示狼的位置
    initWolfState(){
        cc.find("spine_wolf_1", this._mainNode).active = this._slotCnt == 1;
        cc.find("spine_wolf_2", this._mainNode).active = this._slotCnt == 2;
    },

    // 初始化展示石头的位置
    initStoreState(){
        // cc.find("spr_logo_1", this._mainNode).active = this._slotCnt == 1;
        // cc.find("spr_logo_2", this._mainNode).active = this._slotCnt == 2;
    },

    // 设置slots大小
    setSlotsScale(){
        let scaleList = [1.1, 1, 0.9, 0.75];
        this._slots.setScale(scaleList[this._slotCnt-1])
        this._slots.getComponent(cc.Widget).updateAlignment();
    },

    // update (dt) {},
});
