
/**
 * 这是主slots
 */
cc.Class({
    extends: require('LMSlots_Slots_Base'),

    properties: {

    },

    Init(){
        this._spine_stoneLogo = cc.find("spine_stoneLogo", this.node);
        this._spine_stoneLogo.off("click");
        Global.btnClickEvent(this._spine_stoneLogo, this.onClickStone, this);

        this._collectPaw = cc.find("collectpaw", this.node);
        this._collectPaw.off("click");
        Global.btnClickEvent(this._collectPaw, this.onClickPaw, this);

        this._super();

        this.showPawNum(false);
        this.showPawTip();
        this.setRespinState();
    },

    RegisterEvent:function(){
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)// 押注额改变
    },

    // 断线重连
    async ReconnectShow(){
        this.ShowGameview(false);
        if(cc.vv.gameData.getPageReward()){// super免费
            cc.vv.gameData.setIsSuperFree(true);

            cc.vv.gameData.GetBottomScript().ShowFreeModel(true,cc.vv.gameData.GetFreeTime(),cc.vv.gameData.GetTotalFree());
            // 初始化
            cc.vv.gameData.getSuperFreeMgr().initShowSlotsDate();
        }
        else if (cc.vv.gameData.GetTotalFree() > 0){// 免费界面
            this.ShowGameview(true);
            if(cc.vv.gameData.getState() == 1){
                this.setPawState(false);
            }
        }

        // bonus游戏
        let bonusdata = cc.vv.gameData.getBonusGame();
        if(bonusdata) {
            await cc.vv.gameData.getBonusGameMgr().showBonusGame(bonusdata);
        }

        // 结束免费
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
            await this.exitFreeGame();
        }

        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },

    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine:function(msg){
        if(cc.vv.gameData.isSuperFree()) {
            cc.vv.gameData.getSuperFreeMgr().onMsgSpine(msg);
            return
        }

        // msg.resultCards = [2,4,6,3,12,6,6,10,7,12,4,5,10,1,13];
        // msg.resultCards = [13,13,13,13,12,13,13,13,13,12,13,13,13,13,13];
        this._super(msg)
    },

    SetSlotsResult:function(cards){

        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []

        let pawInfo = this._gameInfo.pawInfo;
        let pawIdxs;
        if(pawInfo && pawInfo.idxs){
            pawIdxs = pawInfo.idxs;
        }

        let bonusIdxs = this._gameInfo.bonusIdxs;
        let bonusItems = this._gameInfo.bonusItems;

        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id
                res.data = {}
                let pi = []
                if (Array.isArray(pawIdxs)) {pi = pawIdxs} // By JerryWong
                if(pi && pi.includes(i+1)){
                    res.data.paw = 1;
                }
                let bi = []
                if (Array.isArray(bonusIdxs)) { bi = bonusIdxs }
                if(bi && bi.includes(i+1)){ // By JerryWong
                    res.data.bonus = bonusItems[bonusIdxs.indexOf(i+1)];
                }

                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }

        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //设置reel旋转的状态；
    //是否加速框；
    //是否加速旋转
    //是否停止音效；
    //是否播放背景特效
    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0
            let isContinuous = true
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0 && isContinuous) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount && isContinuous) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                stateInfo.hasRemain = remainingCount >= triggerCount;
                if (stateInfo.continuous && stateInfo.counts[i] > 0 && reelCountOfID == 0) {
                    isContinuous = false
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    //重写：显示bonus中奖
    async OnSpinEnd () {

        //是否能收集能量
        if(this._gameInfo.pawInfo && this._gameInfo.pawInfo.idxs && this._gameInfo.pawInfo.idxs.length > 0){
            await this.playPawFlyAnim()
        }

        // this.hideAllAnit();

        //显示中奖路线
        this.ShowWinTrace();
        await this.playBottomWin();
        let bonusdata = cc.vv.gameData.getBonusGame();
        if(bonusdata){
            await this.gainBonusGame(bonusdata);
        }

        if(cc.vv.gameData.isTriggerFree()){
            await this.gainFreeGame();
        }

         //检测是否免费游戏结束
        if(cc.vv.gameData.isNormalFreeOver()){
            await this.exitFreeGame();
        }

        //下一局
        this.CanDoNextRound();

    },

    //重写
    StartMove:function(){
        if(cc.vv.gameData.isSuperFree()) {
            cc.vv.gameData.getSuperFreeMgr().StartMove();
            return
        }

        if(cc.vv.gameData.isBonusGame()){
            return
        }

        this._super()
        Global.SlotsSoundMgr.playNormalBgm();
    },

    StopMove:function(){
        if(cc.vv.gameData.isSuperFree()) {
            cc.vv.gameData.getSuperFreeMgr().StopMove();
            return
        }

        if(cc.vv.gameData.isBonusGame()){
            cc.vv.gameData.getBonusGameMgr().StopMove();
            return
        }

        this._super()
    },

    // 获得bonus游戏
    gainBonusGame(bonusdata){
        return new Promise(async(success, failed)=>{
            let bonusIdxs = this._gameInfo.bonusIdxs;
            for (let idx of bonusIdxs) {
                let symbol = this.GetSymbolByIdx(idx);
                if(symbol){
                    symbol.playTriggerAnimation()
                }
            }
            Global.SlotsSoundMgr.playEffect("bell");

            await cc.vv.gameData.awaitTime(2);
            await cc.vv.gameData.getUIMgr().showBonusStartUI(bonusdata.spinCnt);
            cc.vv.gameData.getUIMgr().playBonusQPAnim();
            await cc.vv.gameData.awaitTime(0.5);
            await cc.vv.gameData.getBonusGameMgr().showBonusGame(bonusdata);

            success();
        })
    },

    // 获得免费
    gainFreeGame(){
        return new Promise(async(success, failed)=>{

            this.hideAllAnit();

            let result = this._gameInfo.freeResult
            if(result && result.freeInfo && result.freeInfo.scatterIdx){
                let idxs = result.freeInfo.scatterIdx;
                for (let idx of idxs) {
                    let symbol = this.GetSymbolByIdx(idx);
                    if(symbol){
                        symbol.playTriggerAnimation()
                    }
                }
                Global.SlotsSoundMgr.playEffect("bell");
            }
            await cc.vv.gameData.awaitTime(2);

            if(this._gameInfo.freeCnt != this._gameInfo.allFreeCnt){    // 再次
                await cc.vv.gameData.getUIMgr().showFreeGameStartUI(result.freeInfo.freeCnt,"again");
            } else {
                await cc.vv.gameData.getUIMgr().showFreeGameStartUI(result.freeInfo.freeCnt,"first");
                cc.vv.gameData.getUIMgr().playFreeQPAnim();
                await cc.vv.gameData.awaitTime(0.6);
                this.ShowGameview(true);
                this.Backup();
                await cc.vv.gameData.awaitTime(2);
            }
            success();
        })
    },

    // 结束免费
    exitFreeGame(){
        return new Promise(async(success, failed)=>{
            await cc.vv.gameData.awaitTime(1);
            this._bottomScript.ShowBtnsByState("moveing_1")
            await cc.vv.gameData.getUIMgr().showFreeGameEndUI();
            cc.vv.gameData.getUIMgr().playFreeQPAnim();

            await cc.vv.gameData.awaitTime(0.6);
            this.ShowGameview(false);
            this.setPawState(true);

            if(cc.vv.gameData.isBoxGame()) {
                for (let col = 0; col < this._col; col++) {
                    for (let row = 0; row < this._row; row++) {
                        let symbol = this._reels[col].GetSymbolByRow(row);
                        if (symbol) {
                            symbol.ClearState();
                        }
                    }
                }
            }else {
                this.Resume();
            }

            Global.SlotsSoundMgr.stopBgm();

            await cc.vv.gameData.awaitTime(2);
            let nWin = cc.vv.gameData.getFreeWinCoin();
            let nTotal = nWin;
            await new Promise((sucess, failed)=>{
                this.ShowBottomWin(nWin,nTotal,true,sucess)
            });

            if(cc.vv.gameData.isBoxGame()){
                cc.vv.gameData.getBoxGameMgr().openBoxUI();
                cc.vv.gameData.setIsBoxGame(false)
            } else {
                success();
            }
        })
    },

    // 元宝收集动画
    playPawFlyAnim(){
        return new Promise(async(sucess, failed)=>{
            let idxs = this._gameInfo.pawInfo.idxs;

            Global.SlotsSoundMgr.playEffect("symbol_fly");
            idxs.forEach(idx=>{
                let symbol = this.GetSymbolByIdx(idx);
                if(symbol){
                    this.showPawFly(idx, symbol.getPawWPos());
                    symbol.setPaw(false);
                }
            })

            await cc.vv.gameData.awaitTime(0.3);
            sucess();
            //更新爪子数量
            this.showPawNum(true);

            await cc.vv.gameData.awaitTime(0.5);
            let icon = cc.find("collectpaw/pawspine", this.node);
            cc.vv.gameData.playSpine(icon,'animation1',false);

        });
    },

    // 单个爪子收集动画
    async showPawFly(idx,fromWp) {
        if (!this._pawNode) {
            this._pawNode = cc.instantiate(this.node.getChildByName("shoujifly"));
        }
        if (!this._pawEndPos) {
            let icon = cc.find("collectpaw/pawspine", this.node);
            this._pawEndPos = this.node.convertToNodeSpaceAR(icon.convertToWorldSpaceAR(cc.v2(0,0)));
        }
        let pawFly = cc.instantiate(this._pawNode);
        pawFly.active = true;
        let pos = this.node.convertToNodeSpaceAR(fromWp);
        pawFly.position = pos;
        pawFly.parent = this.node;
        let spine = cc.find("spine", pawFly);
        // let self = this;

        cc.vv.gameData.playSpine(spine, "animation1", false);
        await cc.vv.gameData.awaitTime(0.3);
        cc.vv.gameData.playSpine(spine, "animation2", false);
        pawFly.runAction(cc.sequence(cc.moveTo(0.5, this._pawEndPos), cc.destroySelf()));
    },

    // 点击爪子
    onClickPaw(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.isFreeGame()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;

        Global.SlotsSoundMgr.playEffect("click");
        cc.vv.gameData.getBoxGameMgr().openBoxUI();
    },

    // 爪子提示
    showPawTip(){
        let spr_tip = cc.find("tip", this._collectPaw);
        spr_tip.stopAllActions();
        spr_tip.active = true;
        spr_tip.setScale(0)
        spr_tip.runAction(cc.sequence(
            cc.scaleTo(0.5,1,1),
            cc.delayTime(1),
            cc.scaleTo(0.5,0,0),
            cc.callFunc(()=>{ spr_tip.active = false;})
        ))
    },

    // 显示爪子数量
    showPawNum(isRoll){
        let pawstore = cc.vv.gameData.getPawStore();
        let lbl = cc.find("desctext", this._collectPaw);
        if(isRoll){
            let startN = Global.FormatCommaNumToNum(lbl.getComponent(cc.Label).string);
            Global.doRoallNumEff(lbl,startN,pawstore.pawCnt,0.5,null,null,0,true);
        }else {
            lbl.getComponent(cc.Label).string = Global.FormatNumToComma(pawstore.pawCnt);
        }
    },

    // 设置爪子状态
    setPawState(bShow){
        this._collectPaw.active = bShow;
    },

    // 点击石头
    onClickStone(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.isFreeGame()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;

        if (this._bonusLock){
            let needBet = cc.vv.gameData.getNeedBet();
            let allMults = cc.vv.gameData.GetBetMults();

            if(needBet > allMults.length){
            }else {
                cc.vv.gameData.GetBottomScript().SetBetIdx(needBet)
            }
        }

    },

    setRespinState(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        if(curBet >= needBet){
            this._spine_stoneLogo.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
            this._bonusLock = false;
        } else {
            this._spine_stoneLogo.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
            this._bonusLock = true;
        }
    },

    // 押注额改变
    onEventTotalbetUpdated(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        let self = this;
        if(curBet >= needBet && this._bonusLock){
            Global.SlotsSoundMgr.playEffect("unlock");
            let entry = this._spine_stoneLogo.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
            this._spine_stoneLogo.getComponent(sp.Skeleton).setTrackCompleteListener(entry, ()=>{
                this._spine_stoneLogo.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
            });
            this._bonusLock = false;
        } else if(curBet < needBet && !this._bonusLock){
            Global.SlotsSoundMgr.playEffect("lock");
            this._spine_stoneLogo.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
            this._bonusLock = true;
        }
    },

    async playBottomWin () {
        return new Promise((success)=>{
            let nWin = cc.vv.gameData.GetGameWin()
            let nTotal = nWin
            let updateAllCoin = true;
            if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
                nTotal = cc.vv.gameData.GetGameTotalFreeWin()
                updateAllCoin = cc.vv.gameData.GetFreeTime() == 0;
            }
            this.ShowBottomWin(nWin,nTotal,updateAllCoin,()=>{
                success();
            });

        });
    },

    // 隐藏所有的加速框
    hideAllAnit(){
        for (let col = 0 ; col < this._col; col++){
            this._reels[col].ShowAntiEffect(false)
        }
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        cc.vv.gameData.setIsFree(bFree)
        if(bFree){
            Global.SlotsSoundMgr.playBgm("free_bgm");
        }

        this._super(bFree);
    },
});
