    //按节点播放spine
    playSpine:function(node,aniName,loop,endCall){
        if(node){
            node.active = true
            let ske = node.getComponent(sp.Skeleton)
            if(ske){
                ske.setAnimation(0,aniName,loop)
                ske.setCompleteListener(() => {
                    if(endCall){
                        endCall()
                    }
                })
            }
        }
        
    },

    /**
     * 请求子游戏数据51
     * @param gameType
     */
    reqSubGame(dt) {
        return new Promise(res=>{
            this._subCallBack = res;

            let req = {
                c:MsgId.SLOT_SUBGAME_DATA,
                gameid:this._gameId,
                data:dt
            };
            cc.vv.NetManager.send(req, true);
        });
    },

    onRcvSubGameAction(msg){
        if(this._subCallBack){
            this._subCallBack(msg);
            this._subCallBack = null;
        }
    },

