
cc.Class({
    extends: cc.Component,

    properties: {
        _bonusId:3,
    },

    Init () {
        this._bonusId = 3;

        this.node.active = true;
        this._mainNode = cc.find('mainnode',this.node);
        this._mainNode.active = false;
        this._transition2Node = cc.find('transition2',this.node);
        this._topSlotsScript = cc.find('slots_top',this._mainNode).addComponent('Fenrir_BonusSlots');
        this._bottomSlotsScript = cc.find('slots',this._mainNode).addComponent('Fenrir_BonusSlots');
        this._topType = 1;
        this._bottomType = 2;
        this._topSlotsScript.Init(this._topType);
        this._bottomSlotsScript.Init(this._bottomType);

        this._slots_top = cc.find("slots_top", this._mainNode);
        this._slots_bottom = cc.find("slots", this._mainNode);
        // this._spr_wolf = cc.find("slots_top/spr_wolf", this._mainNode);
        this._spine_wolf = cc.find("slots_top/spine_wolf", this._mainNode);
        this._settleNode = cc.find("slots_top/settleNode", this._mainNode);
        this._node_top = cc.find("node_top", this._mainNode);
        this._flyNode = cc.find("flyNode", this._mainNode);

        if(!this._symbolTemplete){
            this._symbolTemplete = cc.vv.gameData.GetPrefabByName("bonus_Symbol");
            if(this._symbolTemplete){
                this._symbolTemplete.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE
            }
        }
    },

    // 断线回到bonus游戏
    async showBonusGame(bonusdata){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playBgm("respin_bgm");
            cc.vv.gameData.setIsBonusGame(true);

            this._subGameData = bonusdata;
            // let state = bonusdata.state;
            if (this._subGameData.state === 1) {  //1代表是商店触发的，需要选择bonus游戏的次数和数量
                await cc.vv.gameData.getUIMgr().showBonusGamePickOneUI();
                this._subGameData = cc.vv.gameData.getBonusGame();

                await cc.vv.gameData.getUIMgr().showBonusStartUI(this._subGameData.totalSpinCnt,2);
                cc.vv.gameData.getUIMgr().playBonusQPAnim();
                await cc.vv.gameData.awaitTime(0.5);
                cc.vv.gameData.GetBottomScript().SetWin(0);
                await this.showBonusGameUI( true);
            } else if (this._subGameData.state === 2) { //2: spin完之后，选择额外spin次数
                await this.showBonusGameUI( false);

                await cc.vv.gameData.getUIMgr().showBonusAddSpinsUI();
                this._subGameData = cc.vv.gameData.getBonusGame();

                this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
                this._totalCnt = this._subGameData.totalSpinCnt;

            } else if (this._subGameData.state === 0) { //0: 正常bonus游戏,
                await this.showBonusGameUI( false);
            }

            // 开始旋转
            this.reqSpine();

            this._callBack = success;
        })
    },

    // 结束bonus游戏
    async endBonusGame(){
        console.log('###bonus游戏结束');
        await this.showBonusSettlement();
        await cc.vv.gameData.getUIMgr().showBonusEndUI(this._subGameData);

        cc.vv.gameData.getUIMgr().playBonusQPAnim();
        await cc.vv.gameData.awaitTime(0.5);

        cc.vv.gameData.GetBottomScript().ShowFreeModel(false)
        this._mainNode.active = false;

        await cc.vv.gameData.awaitTime(2);

        // 赢钱
        await new Promise((sucess, failed)=> {
            let nWin = this._subGameData.winCoin;
            let nTotal = this._subGameData.winCoin;
            if ( cc.vv.gameData.isFreeGame() ) {
                nTotal = cc.vv.gameData.getFreeWinCoin() + this._subGameData.winCoin

                cc.vv.gameData.setFreeWinCoin(nTotal)
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin, nTotal, false, function () {
                    sucess()
                });
            } else {
                cc.vv.gameData.AddCoin(this._subGameData.winCoin);
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin, nTotal, true, function () {
                    sucess()
                });
            }
        });

        if(this._callBack){
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.gameData.setIsBonusGame(false);

            this._callBack();
            this._callBack = null;
            this._subGameData = null;
        }

        if(cc.vv.gameData.isBoxGame() && !cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getBoxGameMgr().openBoxUI();
            cc.vv.gameData.setIsBoxGame(false)
        }
    },

    // 显示bonus游戏  isShop-从商店中获得的bonus游戏
    async showBonusGameUI( isShop){
        return new Promise(async(success, failed)=>{
            this._mainNode.active = true;
            this.lockJackpot(this._subGameData.jackpotValues);

            this._totalCnt = this._subGameData.totalSpinCnt;
            this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
            cc.vv.gameData.GetBottomScript().ShowFreeModel(true,this._curCnt,this._totalCnt)

            this._bonusType = this._subGameData.type;
            this.topShow();

            if(isShop){
                await this.showTriAnimFromShop();
            } else {
                await this.showBonusSlotsUI();
            }

            success();
        })
    },

    // 从商店获得的bonus游戏的触发动画
    async showTriAnimFromShop(){
        return new Promise(async(success, failed) => {
            // let data = cc.vv.gameData.getBonusGame();

            // 1.两个slots在同一个位置，隐藏卷轴
            // let pos_topSlots = this._slots_top.position;
            await cc.vv.gameData.awaitTime(0)
            this._slots_top.position = this._slots_bottom.position;
            this._bottomSlotsScript.initAllSymbol();
            this._topSlotsScript.initAllSymbol();

            // this._spr_wolf.active = false;
            this._spine_wolf.active = false;
            this._settleNode.active = false;

            // 2.下面卷轴展示所有的bonus图标在top层  -- slots[0]为上面卷轴，slots[1]为下面卷轴
            // await this._bottomSlotsScript.showAllBonusSym(data.slots[1].bonusItems);
            await cc.vv.gameData.awaitTime(1);
            await this.playStartSymbolAnim(this._subGameData.slots[1].bonusItems,false);

            // 3.上面卷轴上升，
            Global.SlotsSoundMgr.playEffect("nudge");
            // let pos_wolf = this._spr_wolf.position;
            // this._spr_wolf.position = cc.v2(pos_wolf.x, pos_wolf.y-300);
            // cc.tween(this._spr_wolf).to(0.5, {position:pos_wolf}).start();
            cc.tween(this._slots_top).to(0.5, {position:cc.find("pos_top", this._mainNode).position}).start();
            let spine_xue = cc.find("spine_xue",this._slots_top);
            cc.vv.gameData.playSpine(spine_xue, "animation", false,function () {
                spine_xue.active = false;
            });
            await cc.vv.gameData.awaitTime(0.7);

            // 4.bonus图标从下面卷轴飞到上面卷轴
            await this.playStartSymbolAnim(this._subGameData.slots[0].bonusItems, true);

            // 5.弹出开始页面
            // this._spr_wolf.active = false;
            cc.vv.gameData.playSpine(this._spine_wolf, "animation", true);
            this.initSettleState();
            await cc.vv.gameData.getUIMgr().showBonusDoubleStartUI();

            success();
        })
    },

    // 初始显示slots
    async showBonusSlotsUI(){
        return new Promise(async(success, failed) => {
            // let data = cc.vv.gameData.getBonusGame();

            this._bottomSlotsScript.initAllSymbol();
            this._topSlotsScript.initAllSymbol();

            this.scheduleOnce(()=>{
                this._slots_top.position = cc.find("pos_top", this._mainNode).position;

                // this._spr_wolf.active = false;
                this.initSettleState();

                let self = this;
                this._subGameData.slots[1].bonusItems.forEach(item=>{
                    self.showSymbolNormalAnim(item, false);
                })
                this._subGameData.slots[0].bonusItems.forEach(item=>{
                    self.showSymbolNormalAnim(item, true);
                })
            }, 0);

            await cc.vv.gameData.awaitTime(2);

            success();
        });
    },

    // 显示symbol
    showSymbolNormalAnim(data, isTop){
        let col = data.idx-1;

        let slots = isTop ? this._topSlotsScript : this._bottomSlotsScript;
        let symbol = slots.GetSymbolByIdx(data.idx);
        symbol.ShowById(this._bonusId, {bonus:data});
        symbol.playBonusFireAnim(true);
    },

    // 商店获得的bonus游戏，bonus节点放置到顶层时的触发动画   isTop-是否是上面卷轴
    playStartSymbolAnim(bonusItems,isTop) {
        return new Promise(async (success, failed) => {

            bonusItems.sort(function (a, b) {
                return a.idx / 5 - b.idx / 5
            }).sort(function (a, b) {
                return (a.idx - 1) % 5 - (b.idx - 1) % 5
            });

            for (let i = 0; i < bonusItems.length; i++) {
                let col = bonusItems[i].idx - 1;
                let coin = bonusItems[i].coin;
                let jp = bonusItems[i].jackpot;

                if(isTop){
                    let symbol = this._topSlotsScript.GetSymbolByIdx(bonusItems[i].idx)

                    let flyNode = cc.instantiate(this._flyNode);
                    flyNode.parent = this._node_top;
                    let moon = cc.find("moon", flyNode);
                    let burst = cc.find("burst", flyNode);
                    moon.active = false;
                    burst.active = false;

                    let startNode = this._bottomSlotsScript.GetSymbolByIdx(bonusItems[i].idx).node;
                    flyNode.position = this._node_top.convertToNodeSpaceAR(startNode.convertToWorldSpaceAR(cc.v2(0,0)));
                    let endPos = this._node_top.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));

                    moon.active = true;
                    moon.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                    cc.tween(flyNode)
                        .to(0.5, {position:endPos})
                        .call(()=>{
                            moon.active = false;
                            symbol.ShowById(this._bonusId, {bonus:bonusItems[i]});
                            symbol.playBonusFireAnim(true);
                            burst.active = true;
                            burst.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                            burst.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                flyNode.destroy()
                            })
                        })
                        .start();

                }else {
                    let symbol = this._bottomSlotsScript.GetSymbolByIdx(bonusItems[i].idx)
                    symbol.ShowById(this._bonusId, {bonus:bonusItems[i]});
                    symbol.playBonusQuanAnim(true);
                    symbol.playBonusZoomAnim(true);
                }

                await cc.vv.gameData.awaitTime(0.2);
            }

            await cc.vv.gameData.awaitTime(0.5);
            success();
        })
    },

    // 初始展示结算框
    initSettleState(){
        this._settleNode.active = true
        cc.find("jiesuo", this._settleNode).active = this._bonusType == 1;
        cc.find("jiesuo2", this._settleNode).active = this._bonusType == 2;
        cc.vv.gameData.playSpine(cc.find(this._bonusType == 1?"jiesuo":"jiesuo2", this._settleNode),'animation2',false);

        cc.find("settlement", this._settleNode).active = false;
        cc.find("settlement/winner", this._settleNode).active = true;
        for (let i = 1; i <= 5; i++){
            cc.find("settlement/jp_"+i, this._settleNode).active = false;
        }
    },


    //顶部冰雪覆盖状态type = isStore and BonusGameType.double or BonusGameType.single,  
    //-- 1： 代表普通bonus游戏, 2: 代表两个slot的bonus游戏
    topShow(){
        let topnode = cc.find('top_lock',this._mainNode);
        topnode.active = this._bonusType==2?false:true;
    },

    //展示bonus结算coin效果
    showBonusSettlement(){
        return new Promise(async (success, failed) => {

            Global.SlotsSoundMgr.playEffect("logo_transition");
            let jiesuo = cc.find(this._bonusType == 1?"jiesuo":"jiesuo2", this._settleNode);
            let settlement = cc.find("settlement",  this._settleNode);
            let shownode = cc.find('uishowani', settlement);
            let coinnode = cc.find('collectcoin', settlement);
            coinnode.getComponent(cc.Label).string = '';
            cc.vv.gameData.playSpine(jiesuo, 'animation1', false);

            await cc.vv.gameData.awaitTime(1);
            settlement.active = true;
            cc.vv.gameData.playSpine(shownode, 'animation1', false);

            await cc.vv.gameData.awaitTime(1);

            //开始飞入 收集coin
            let slots = this._subGameData.slots;
            let curtotal = 0;
            let lblsettlement = cc.find('slots_top/settleNode/settlement/collectcoin',this._mainNode);
            lblsettlement.getComponent(cc.Label).string = "";
            if(this._subGameData.type == 2){
                await this.collectSlotsCoin(this._topType,this._topSlotsScript,curtotal,slots[0].bonusItems);
                curtotal = Global.FormatCommaNumToNum(lblsettlement.getComponent(cc.Label).string)
            }
            await this.collectSlotsCoin(this._bottomType,this._bottomSlotsScript,curtotal,slots[1].bonusItems);
            await cc.vv.gameData.awaitTime(1);

            success();
        });
    },

    //收集按slots从上到下收集
    async collectSlotsCoin(slotsType,slotscript,curtotal,bonusitems){
        return new Promise(async(success)=>{
            let self = this;
            let spine_sj = cc.find('spine_sj',this._mainNode);
            let spine_sj_2 = cc.find("spine_sj_2",this._mainNode);
            let settlement = cc.find('slots_top/settleNode/settlement',this._mainNode);
            let lblsettlement = cc.find('collectcoin',settlement).getComponent(cc.Label);
            let collectparticle = cc.find('shoujijieshu',settlement).getComponent(cc.ParticleSystem);
            spine_sj_2.active = false;

            let isDouble = bonusitems.length === 15;// 集满了，需要飞特效两次，结果为双倍

            if(isDouble){
                await cc.vv.gameData.getUIMgr().showBonusDoubleWin(slotsType== this._bottomType?1:2);
            }

            bonusitems.sort((a,b)=>{return a.idx - b.idx});
            for(let index = 0; index < bonusitems.length; index++){
                let idx = bonusitems[index].idx;
                let symbol = slotscript.GetSymbolByIdx(idx)

                // 飞特效
                if(bonusitems[index].jackpot){
                    cc.find("winner", settlement).active = false;
                    cc.find("jp_"+bonusitems[index].jackpot.id, settlement).active = true;
                }

                let startpos = self._mainNode.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));
                spine_sj.position = startpos;
                let scale = self.getScaleMul(idx, slotsType);
                let newangle = self.getRotationAngle(idx, slotsType);
                spine_sj.angle = newangle;
                spine_sj.scaleY = scale;
                Global.SlotsSoundMgr.playEffect("respin_calculate1");
                cc.vv.gameData.playSpine(spine_sj,'animation'+slotsType,false,()=>{
                    collectparticle.resetSystem();
                });
                if(isDouble){
                    await cc.vv.gameData.awaitTime(0.2);
                    spine_sj_2.position = startpos;
                    spine_sj_2.angle = newangle;
                    spine_sj_2.scaleY = scale;
                    Global.SlotsSoundMgr.playEffect("respin_calculate1");
                    cc.vv.gameData.playSpine(spine_sj_2,'animation'+slotsType,false);
                }
                // 清除光效
                symbol.playBonusFireAnim(false);
                // 加钱
                if(bonusitems[index].coin){
                    curtotal +=  bonusitems[index].coin;
                } else if(bonusitems[index].jackpot){
                    curtotal +=  bonusitems[index].jackpot.value;
                }
                if(isDouble){
                    await cc.vv.gameData.awaitTime(0.3);
                    lblsettlement.string = Global.FormatNumToComma(curtotal);
                    if(bonusitems[index].coin){
                        curtotal +=  bonusitems[index].coin;
                    } else if(bonusitems[index].jackpot){
                        curtotal +=  bonusitems[index].jackpot.value;
                    }
                    await cc.vv.gameData.awaitTime(0.2);
                }else {
                    await cc.vv.gameData.awaitTime(0.5);
                }

                Global.SlotsSoundMgr.playEffect("respin_calculate2");
                lblsettlement.string = Global.FormatNumToComma(curtotal);

                await cc.vv.gameData.awaitTime(0.5);
                if(bonusitems[index].jackpot){
                    cc.find("winner", settlement).active = true;
                    cc.find("jp_"+bonusitems[index].jackpot.id, settlement).active = false;
                }
            }

            success();
        })
    },

    //奖池锁定(停止滚动)
    lockJackpot(jackpotvalus){
        let prizepool = cc.find('LMSlots_PrizePool2',this._mainNode).getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{prizeType:0,pauseNum:jackpotvalus[0]},{prizeType:1,pauseNum:jackpotvalus[1]},
            {prizeType:2,pauseNum:jackpotvalus[2]},{prizeType:3,pauseNum:jackpotvalus[3]},{prizeType:4,pauseNum:jackpotvalus[4]}]);
    },


    //点击开始移动
    startSpin(){

    },

    //显示结果
    showSpinResult(){

    },

    //返回51请求结果
    getSubGameData(){
        return this._subGameData;
    },

    //旋转停止
    spinEnd(){
        
    },

    // OnReelSpinEnd(colIdx){
        // this._bottomSlotsScript.OnSlotsSpinEnd(colIdx);
        // this._topSlotsScript.OnSlotsSpinEnd(colIdx);
    // },

    //bonus游戏旋转结果请求
    async reqSpine(){
        cc.log(cc.js.formatStr("startMove:%s, %s", this._curCnt, this._totalCnt));

        this._curCnt += 1
        cc.vv.gameData.GetBottomScript().ShowFreeModel(true,this._curCnt,this._totalCnt);
        this._topSlotsScript.StartMove(this._subGameData.slots[0].bonusIdxs);
        this._bottomSlotsScript.StartMove(this._subGameData.slots[1].bonusIdxs);

        await cc.vv.gameData.awaitTime(1);
        let reqdata = {rtype:3};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._subGameData = result.data.bonusGame;
            cc.vv.gameData.setBonusGame(this._subGameData);

            this._bottomSlotsScript.setSpinResult(this._subGameData.slots[1].bonusIdxs, this._subGameData.slots[1].bonusItems);
            this._topSlotsScript.setSpinResult(this._subGameData.slots[0].bonusIdxs, this._subGameData.slots[0].bonusItems);
        }
    },

    //点击停止按钮调用
    StopMove:function(){
        this._topSlotsScript.StopMove();
        this._bottomSlotsScript.StopMove();
    },

    async OnSpinEnd(){
        cc.log("OnSpinEnd")

        // let bonusdata = cc.vv.gameData.getBonusGame();
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        // this.bonusGameHandle(bonusdata);

        await cc.vv.gameData.awaitTime(1);
        if(this._subGameData.state == 2){
            //state未表示需要添加spin界面
            await cc.vv.gameData.getUIMgr().showBonusAddSpinsUI();
            this._subGameData = cc.vv.gameData.getBonusGame();

            this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
            this._totalCnt = this._subGameData.totalSpinCnt;
            this.reqSpine();
        }else{
            //此处进入bonus游戏后 不会调用
            if(this._subGameData.spinCnt > 0){
                cc.vv.gameData.awaitTime(1);
                this.reqSpine();
            }else{
               this.endBonusGame();
            }
        }
    },

    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        let topEndIdx = this._topSlotsScript.GetLastStopReelIdx();
        let bottomEndIdx = this._bottomSlotsScript.GetLastStopReelIdx();

        let lastIdx = bottomEndIdx ? bottomEndIdx : topEndIdx;
        let stopType = bottomEndIdx ? this._bottomType : this._topType;

        return {slotType:stopType, reelIdx:lastIdx};
    },

    getMaxReelIdx(type, col){
        let reelList = type == this._topType ? this._topSlotsScript.getLastStopReel() : this._bottomSlotsScript.getLastStopReel();
        return reelList[col];
    },

    //获取旋转角度
    getRotationAngle(col, type){
        let list = []
        if(type == this._topType){
            list = [-60,-40,0,40,60, -45,-25,0,25,45, -35,-20,0,20,35];
        } else {
            list = [-28,-15,0,15,28, -23,-12,0,12,23, -20,-10,0,10,20];
        }

        return list[col-1];
    },

    //获取缩放比例
    getScaleMul(col, type){
        let list = [];
        if(type == this._topType) {
            list = [1.2,0.9,0.7,0.9,1.2, 1.4,1.2,1.1,1.2,1.4, 1.8,1.6,1.5,1.6,1.8];
        }else {
            list = [0.95,0.9,0.85,0.9,0.95, 1.1,1.05,1,1.05,1.1, 1.25,1.2,1.2,1.2,1.25];
        }

        return list[col-1];
    },

});
