
cc.Class({
    extends: require('LMSlots_Slots_Base'),

    properties: {
        _wildCols:[],
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //初始化
    Init:function(type){
        this._slotsType = type;
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = this._cfg.col
        this._row = this._cfg.row

        this._topAniNode = cc.find("top_ani",this.node)
        this.createReels(this._col,this._row, type)

        // this._bottomScript.ShowBtnsByState("idle")

        // this.RegisterEvent()

        //断线重连的显示
        // this.ReconnectShow()

        //初始化奖池
        // this.CheckJoopLock()
    },

    //创建卷轴
    createReels:function(col,row,type){
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this.node)
            let scp = node.addComponent("Fenrir_SFreeReel")
            scp.Init(i,row,this._topAniNode)
            scp.setSlotType(type);
            this._reels.push(scp)

        }
    },

    // 设置wild所在的列
    setWildCols(cols){
        this._wildCols = cols;

        for (let i = 0; i < cols.length; i++){
            for(let row = 0; row < this._row; row++){
                this._reels[cols[i]-1].GetSymbolByRow(row).ShowById(1);
            }
        }
    },

    // 初始化所有节点，
    iniAllSymbol(){
       for (let col = 0; col < this._reels.length; col++) {
           for (let row = 0; row < this._row; row++) {
               this._reels[col].GetSymbolByRow(row).ClearState();
           }
       }
    },


    //点击旋转按钮调用
    StartMove:function(){
        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        let reels = [];
        let self = this;
        this._reels.forEach(reel=>{
            if(!this._wildCols.includes(reel.GetReelIdx()+1)){
                reels.push(reel)
            }else {
                for (let row = 0; row < self._row; row++){
                    reel.GetSymbolByRow(row).ClearState();
                }
            }
        });
        this.MoveReels(reels)

        //设置停止时间
        //就是从开始旋转，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()
    },


    onMsgSpine:function(data){
        this._gameInfo = data
        let cards = data.cards
        this.SetSlotsResult(cards)
    },

    OnSpinEnd:function () {
        this.ShowWinTrace()
    },

    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        let nIter = this._cfg.reelStopInter || 0.6

        let pageReward = cc.vv.gameData.getPageReward();
        let col = this._col * (pageReward.slotCnt - this._slotsType);

        return (reelIdx + col)*nIter;
    },

    // update (dt) {},
});
