
cc.Class({
    extends: cc.Component,

    properties: {
       // mainNode:cc.Node,
       // topSpineNode:cc.Node,
    },

    Init(){
        this.node.active = true;
        this._mainNode = cc.find("mainnode", this.node);
        this._mainNode.active = false;
        this._btn_close = cc.find('mainnode/uinode/btn_close',this.node)
        this._btn_close.off("click")
        Global.btnClickEvent(this._btn_close,this.onCloseUI,this)


        this._box_tip = cc.find("mainnode/uinode/box_tip", this.node);
        this._box_tip.active = false;
        this._spr_tip = cc.find('mainnode/uinode/node_paw/spr_tip',this.node)
        this._spr_tip.active = false;
        let btn_help = cc.find('mainnode/uinode/node_paw/btn_help',this.node)
        Global.btnClickEvent(btn_help,this.onOpenHelp,this)

        let btn_left = cc.find('mainnode/uinode/btn_leftmove',this.node)
        Global.btnClickEvent(btn_left,this.onBoxLastLevel,this)

        let btn_right = cc.find('mainnode/uinode/btn_rightmove',this.node)
        Global.btnClickEvent(btn_right,this.onBoxNextLevel,this)

        this._topSpineNode = cc.find("uinode/topspine", this._mainNode)

    },

    //显示宝箱界面
    openBoxUI(){
        Global.SlotsSoundMgr.playEffect("shop_open");
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")

        this._pawStore = cc.vv.gameData.getPawStore();
        this._curPage = this._pawStore.unlockPage;
        let masknode = cc.find('mask',this._mainNode);
        let uinode = cc.find('uinode',this._mainNode);
        masknode.opacity = 0;
        uinode.scale = 0;
        this._mainNode.active = true;
        cc.tween(masknode).to(0.3,{opacity:255}).start();
        cc.tween(uinode).to(0.3,{scale:1},{easing:'backOut'}).start();

        cc.vv.gameData.setCanClickBox(true);
        this.loadBoxData();
    },

    // 关闭宝箱界面
    async closeBoxUI(){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playEffect("shop_close");

            let masknode = cc.find('mask', this._mainNode);
            let uinode = cc.find('uinode', this._mainNode);
            masknode.opacity = 0;
            uinode.scale = 0;
            cc.tween(masknode).to(0.3, {opacity: 0}).start();
            cc.tween(uinode).to(0.3, {scale: 0}).start();

            await cc.vv.gameData.awaitTime(0.3)
            this._mainNode.active = false;
            success();
        })
    },
    
    //播放顶部spine动画
    topPlaySpine(){
        //默认打开第一页
        let type = this._pawStore.unlockPage >= this._curPage?2:1;
        cc.vv.gameData.playSpine(this._topSpineNode,cc.js.formatStr('animation%s_%s',this._curPage,type),false);
    },

    //页面点显示
    pagePointShow(bBlink){
        let pointsnode = cc.find('mainnode/uinode/bottompoints',this.node);
        for(let i=1;i<5;i++){
            let pointnode = cc.find(cc.js.formatStr('point%s/choice',i),pointsnode);
            if(i==this._curPage){
                pointnode.active = true;
                if(bBlink){
                    cc.vv.gameData.playSpine(pointnode,"animation",false,function () {
                        cc.vv.gameData.playSpine(pointnode,"animation2",true);})
                } else {
                    cc.vv.gameData.playSpine(pointnode,"animation2",true);
                }
            }else {
                pointnode.active = false;
            }


        }
    },

    // 更新爪子数
    updatePawNum(){
        this._pawStore = cc.vv.gameData.getPawStore();
        //底部爪子数量显示
        let pawcntnode = cc.find('mainnode/uinode/node_paw/desctext',this.node);
        pawcntnode.getComponent(cc.Label).string = Global.FormatNumToComma(this._pawStore.pawCnt);
        //还要更新主界面的爪子数量
        cc.vv.gameData.GetSlotsScript().showPawNum(false);
    },

    // 更新其他箱子
    updataOtherBox(){
        if(this._pawStore.unlockPage != this._curPage){ // 全打开了，不用判断金币
            return
        }

        let pagedetail = this.getPageDetail();
        if(this._pawStore.pawCnt <pagedetail.price){
            let contentnode = cc.find('mainnode/uinode/bottombg/baoxiangview/view/content',this.node);
            for (let i=1;i<10;i++){
                let itemnode = cc.find(cc.js.formatStr('item%s',i),contentnode);
                let unlockdetail = this.getUnlockItems(i);
                if(unlockdetail) {
                    //已经购买
                    this.setBoxState(itemnode, 4);
                }
                else {
                    if(this._pawStore.pawCnt <pagedetail.price){
                        //不能购买
                        this.setBoxState(itemnode,3);
                    }else{
                        this.setBoxState(itemnode,2);
                    }
                }
            }
        }

    },

    //加载当前宝箱数据
    loadBoxData(){
        this.refreshDataWithAction(0);
        this.showBoxState();
        this.updatePawNum();
        this.topPlaySpine();
        this.pagePointShow();
    },

    //按页面显示宝箱状态
    showBoxState(isreset=false){
        let pagedetail = this.getPageDetail();
        let contentnode = cc.find('mainnode/uinode/bottombg/baoxiangview/view/content',this.node);
        for(let i=1;i<10;i++){
            let itemnode = cc.find(cc.js.formatStr('item%s',i),contentnode);
            cc.find('bg_show/costnum',itemnode).getComponent(cc.Label).string = Global.FormatNumToComma(pagedetail.price);
            
            // itemnode.getComponent('Fenrir_Boxitem').resetState(isreset);

            //先判断是否解锁
            if(this._pawStore.unlockPage >= this._curPage){
                //已经解锁
                let unlockdetail = this.getUnlockItems(i);
                if(unlockdetail){
                    //已经购买
                    this.setBoxState(itemnode,4);
                    itemnode.getComponent('Fenrir_Boxitem').showBoxState(unlockdetail, true);
                }else{
                    if(this._pawStore.pawCnt <pagedetail.price){
                        //不能购买
                        this.setBoxState(itemnode,3);
                    }else{
                        this.setBoxState(itemnode,2);
                    }
                }
            }else{
                //未解锁
                this.setBoxState(itemnode,1);
            }
        }
    },

    async refreshDataWithAction(deltaX) {

        let contentnode = cc.find('mainnode/uinode/bottombg/baoxiangview/view/content',this.node);

        if(deltaX != 0){
            Global.SlotsSoundMgr.playEffect("page_next");

            contentnode.stopAllActions();
            contentnode.x = 0;
            contentnode.runAction(cc.sequence(cc.spawn(cc.fadeTo(0.15,63),cc.moveBy(0.15,deltaX,0)),
                cc.spawn(cc.fadeTo(0.15,255),cc.moveBy(0.15,-deltaX,0))));

            await cc.vv.gameData.awaitTime(0.15);
        }

        for(let i=1; i<=9; i++){
            let itemnode = cc.find(cc.js.formatStr('item%s',i),contentnode);
            itemnode.setScale(0.1);

            itemnode.stopAllActions();
            itemnode.runAction(cc.scaleTo(0.1*i, 1,1).easing(cc.easeBackOut()))
        }
    },

    //设置宝箱状态(未解锁1/解锁可以购买2/解锁不能购买3)
    setBoxState(itemnode,state){
        cc.find('baoxiang',itemnode).active = state==2;
        cc.find('baoxiang_lock',itemnode).active = state==3;
        cc.find('baoxiang_ice',itemnode).active = state==1;
        cc.find('baoxiangspine',itemnode).active = state==4;
        if(state != 4){
            cc.find('getcoin',itemnode).active = false;
        }
        // cc.find('getcoin',itemnode).active = state==4;
        cc.find('bg_show', itemnode).active = state != 4
        itemnode.getComponent('Fenrir_Boxitem').changeBoxState(this._curPage,state);
    },

    //获取页面数据
    getPageDetail(){
        let pagedetails = this._pawStore.pageDetails;
        return pagedetails[this._curPage-1];
    },

    //获取解锁items 位置从1开始
    getUnlockItems(idx){
        let unlockitems = this._pawStore.unlockItems[this._curPage-1];
        if(unlockitems){
            for(let i=0;i<unlockitems.length;i++){
                if(unlockitems[i].idx == idx){
                    return unlockitems[i];
                }
            }
        }
    },

    //关闭界面
    async onCloseUI(){
        Global.SlotsSoundMgr.playEffect("click");
        this._btn_close.getComponent(cc.Button).interactable = false;

        await this.closeBoxUI();
        cc.vv.gameData.GetBottomScript().CanDoNextRound();
        this._btn_close.getComponent(cc.Button).interactable = true;
    },

    //打开帮助
    onOpenHelp(){
        this._spr_tip.stopAllActions();
        if(this._spr_tip.active){
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(this._spr_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        } else {
            Global.SlotsSoundMgr.playEffect("tips_popup");

            this._spr_tip.active = true;
            this._spr_tip.setScale(0);
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        }
    },

    showBoxTip(node){

        this._box_tip.stopAllActions();
        if(this._box_tip.active){
            this._box_tip.runAction(cc.sequence(
                cc.scaleTo(this._box_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false;})
            ))
        } else {
            this._box_tip.position = this._box_tip.parent.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0,0)));
            this._box_tip.active = true;
            this._box_tip.setScale(0);
            this._box_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false;})
            ))
        }
    },

    //宝箱显示左移动
    async onBoxLastLevel(){
        if(!cc.vv.gameData.canClickBox()){
            return;
        }
        cc.vv.gameData.setCanClickBox(false);

        if(this._curPage<=1){
            this._curPage = 4;
        }else{
            this._curPage--;
        }
        this.topPlaySpine();
        this.pagePointShow(true);
        this.refreshDataWithAction(20);
        this.showBoxState(true);

        await cc.vv.gameData.awaitTime(1.1);
        cc.vv.gameData.setCanClickBox(true);
    },

    //宝箱显示右移动
    async onBoxNextLevel(){
        if(!cc.vv.gameData.canClickBox()){
            return;
        }
        cc.vv.gameData.setCanClickBox(false);

        if(this._curPage>=4){
            this._curPage = 1;
        }else{
            this._curPage++;
        }
        this.topPlaySpine();
        this.pagePointShow(true);
        this.refreshDataWithAction(-20);
        this.showBoxState(true);

        await cc.vv.gameData.awaitTime(1.1);
        cc.vv.gameData.setCanClickBox(true);
    },

    async gainSpecial(selectRes){
        cc.vv.gameData.setIsBoxGame(true);

        await cc.vv.gameData.awaitTime(0.5);
        this.closeBoxUI();

        if (selectRes.bonusGame) {    // bonus
            cc.vv.gameData.getBonusGameMgr().showBonusGame(selectRes.bonusGame);
            cc.vv.gameData.GetBottomScript().SetWin(0);
        } else if (selectRes.freeInfo && selectRes.freeInfo.freeCnt > 0) {   // free
            cc.vv.gameData.SetTotalFree(selectRes.freeInfo.freeCnt);
            cc.vv.gameData.SetFreeTime(selectRes.freeInfo.freeCnt);

            await cc.vv.gameData.awaitTime(0.5);
            await cc.vv.gameData.getUIMgr().showFreeGameStartUI(selectRes.freeInfo.freeCnt,"first");
            cc.vv.gameData.getUIMgr().playFreeQPAnim();
            await cc.vv.gameData.awaitTime(0.6);
            cc.vv.gameData.GetBottomScript().SetWin(0);
            cc.vv.gameData.GetSlotsScript().ShowGameview(true);
            cc.vv.gameData.GetSlotsScript().setPawState(false);
            await cc.vv.gameData.awaitTime(2);
            cc.vv.gameData.GetBottomScript().CanDoNextRound();
        } else if (selectRes.pageReward) {   // superfree
            cc.vv.gameData.setPageReward(selectRes.pageReward);
            cc.vv.gameData.setIsSuperFree(true);
            cc.vv.gameData.SetTotalFree(selectRes.pageReward.freeCnt);
            cc.vv.gameData.SetFreeTime(selectRes.pageReward.freeCnt);

            await cc.vv.gameData.awaitTime(0.5);
            await cc.vv.gameData.getUIMgr().showSuperFreeStartFreeUI(this._curPage);
            cc.vv.gameData.getUIMgr().playFreeQPAnim();
            await cc.vv.gameData.awaitTime(0.6);
            cc.vv.gameData.GetBottomScript().SetWin(0);
            cc.vv.gameData.GetBottomScript().ShowFreeModel(true, 0, selectRes.pageReward.freeCnt);
            // 初始化
            cc.vv.gameData.getSuperFreeMgr().initShowSlotsDate();
            await cc.vv.gameData.awaitTime(2);
            cc.vv.gameData.GetBottomScript().CanDoNextRound();
        }
    },

});
